"""Переклад рубрик і заголовків молитов з prayers_ru_pr українською (використовує build_kz_molytvy.py).
head(s) і rub(s) приймають рядок без розмітки, з латинськими двійниками вже виправленими; None — невідомий рядок (потрапить
у звіт «НЕ ПЕРЕКЛАДЕНО»), '' — рядок не переноситься (довідка про видання, посилання тощо)."""
import re

import unicodedata

_LAT = dict(zip('aceopxyiABCEHKMOPTXI', 'асеорхуіАВСЕНКМОРТХІ'))
_LAT.update({'э': 'е', 'Э': 'Е', 'ё': 'е', 'Ё': 'Е'})


def _fl(s):
    """Ключ у нормалізованому вигляді, як після fix_latin у build_kz_akafisty.py: латинські двійники кирилиці → кирилиця, э/ё → е, NFC."""
    s = unicodedata.normalize('NFD', s).replace('е\u0308', 'е').replace('Е\u0308', 'Е')
    if re.search(r'[\u0400-\u04FF]', s): s = ''.join(_LAT.get(c, c) for c in s)
    return unicodedata.normalize('NFC', s)


