def inline(key):
    """Позначка всередині рядка («(імена)», «(поклін)», закінчення «(-шая)») → українською (вже в транслітерації)."""
    if key in INLINE: return INLINE[key]
    m = re.fullmatch(r'\(?\s*(\d+) раз\)?\.?', key)
    if m: return f'({m[1]} разів)'
    if TRANSLIT and re.fullmatch(r'[\(\[]?[-–]?[а-яёА-ЯЁ,\s\-–.:]+[\)\]]?[.,]?', key) and len(key) < 60 and key not in NOTRANS:
        return TRANSLIT(key).strip()
    return None


