def head(s):
    """Заголовок розділу → українською; None — невідомий (потрапить у звіт «НЕ ПЕРЕКЛАДЕНО»)."""
    if s in EXACT: return EXACT[s]
    m = re.fullmatch(r'Псалом (\d+)', s)
    if m: return f'Псалом {m[1]}'
    return None


def rub(s):
    if s in RUB: return RUB[s]
    if s in INLINE: return INLINE[s]
    if s in EXACT: return EXACT[s]
    if s in RUB_UK: return RUB_UK[s]
    return None


