EXACT.update({_fl(k): v for k, v in _TK.items()})
RUB.update({_fl(k): v for k, v in _TK.items() if k.startswith('*')})

# ---------------------------------------------------------------- нормалізація ключів і загальні шаблони
EXACT = {_fl(k): v for k, v in EXACT.items()}
RUB = {_fl(k): v for k, v in RUB.items()}
RUB_UK = {_fl(k): v for k, v in RUB_UK.items()}
INLINE = {_fl(k): v for k, v in INLINE.items()}


def _generic(key):
    m = re.fullmatch(r'Ирмос (\d+)-(?:й|ой) песни:?', key)
    if m: return f'Ірмос {m[1]}-ї пісні:'
    m = re.fullmatch(r'Стих (\d+):', key)
    if m: return f'Стих {m[1]}:'
    if key in (')', ']', '(', '['): return key
    return None


_inline_a = inline


def inline(key):
    key = _fl(key)
    if key in RUB and key not in INLINE: return RUB[key]
    u = _inline_a(key)
    if u is not None: return u
    u = _generic(key)
    if u is not None: return u
    # кілька груп у дужках поспіль: «(Трижды.) (Поклон.)», «(имя) (рабе Твоей)»
    parts = re.findall(r'\([^)]*\)|[^()\s][^()]*', key)
    if len(parts) > 1 and ''.join(parts).replace(' ', '') == key.replace(' ', ''):
        out = [inline(x.strip()) for x in parts]
        if all(x is not None for x in out): return ' '.join(out)
    if key in RUB_UK: return RUB_UK[key]
    if key in RUB: return RUB[key]
    if re.fullmatch(r'(.+?)\s*(Слава, и ныне:)', key): pass
    m = re.fullmatch(r'\((\d+ раз|Трижды)\)\.? Слава, и ныне:', key)
    if m: return ('(' + ('тричі' if m[1] == 'Трижды' else m[1].replace('раз', 'разів')) + ') Слава, і нині:')
    return None


def rub(s):
    if s in RUB: return RUB[s]
    if s in INLINE: return INLINE[s]
    if s in EXACT: return EXACT[s]
    if s in RUB_UK: return RUB_UK[s]
    return _generic(s)
